var fitTimberRecipeEnvelope = (parts, ware) => {
  const appearance = woodWareAppearance(ware);
  if (!appearance) return;
  const layout = CART_CARGO_LAYOUTS[appearance.base];
  const target2 = [layout.width / layout.scale, layout.height / layout.scale, layout.depth / layout.scale];
  const bounds2 = parts.map((part2) => getRomanPartBounds(part2));
  const min = target2.map((_value, axis) => Math.min(...bounds2.map((box2) => box2.min[axis])));
  const max = target2.map((_value, axis) => Math.max(...bounds2.map((box2) => box2.max[axis])));
  const scale2 = target2.map((value, axis) => value / (max[axis] - min[axis]));
  for (const part2 of parts) {
    part2.position = part2.position.map((value, axis) => (value - (min[axis] + max[axis]) / 2) * scale2[axis]);
    const localScale = [...scale2];
    if (Math.abs(DMath.sin(part2.rotation?.[2] ?? 0)) > 0.5)
      [localScale[0], localScale[1]] = [localScale[1], localScale[0]];
    if (Math.abs(DMath.sin(part2.rotation?.[0] ?? 0)) > 0.5)
      [localScale[1], localScale[2]] = [localScale[2], localScale[1]];
    part2.size = part2.size.map((value, axis) => value * localScale[axis]);
  }
};

