// src/render-common/buildings/roman-flour-stock.ts
var fitRomanFlourStock = (definition, recipe, detailed) => {
  const slots2 = recipe.parts.filter((part2) => part2.stock?.ware === "flour");
  if (!slots2.length) return;
  const canonical = createWareRecipe("flour", detailed).parts;
  const bottom = Math.min(...canonical.map((part2) => getRomanPartBounds(part2).min[1]));
  const scale2 = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  const keys = new Set(slots2.map((part2) => `${part2.stock.kind}:${part2.stock.slot}`));
  recipe.parts = recipe.parts.filter((part2) => part2.stock?.ware !== "flour");
  for (const key5 of keys) {
    const pieces = slots2.filter((part2) => `${part2.stock.kind}:${part2.stock.slot}` === key5);
    const bounds2 = pieces.map((part2) => getRomanPartBounds(part2));
    const minimum2 = [0, 1, 2].map((axis) => Math.min(...bounds2.map((bound) => bound.min[axis])));
    const maximum2 = [0, 1, 2].map((axis) => Math.max(...bounds2.map((bound) => bound.max[axis])));
    const center = [
      (minimum2[0] + maximum2[0]) / 2,
      minimum2[1] - bottom * scale2,
      (minimum2[2] + maximum2[2]) / 2
    ];
    for (const part2 of canonical) recipe.parts.push({
      ...part2,
      stock: pieces[0].stock,
      position: part2.position.map((value, axis) => center[axis] + value * scale2),
      size: part2.size.map((value) => value * scale2)
    });
  }
};

// src/render-common/buildings/roman-grain-stock.ts
var fitRomanMillGrainStock = (definition, recipe) => {
  if (definition.id !== MILL_TYPE_ID) return;
  const parts = recipe.parts.filter((part2) => part2.stock?.ware === "grain");
  if (!parts.length) return;
  const bounds2 = parts.map((part2) => getRomanPartBounds(part2));
  const minimum2 = [0, 1, 2].map((axis) => Math.min(...bounds2.map((bound) => bound.min[axis])));
  const maximum2 = [0, 1, 2].map((axis) => Math.max(...bounds2.map((bound) => bound.max[axis])));
  const pivot = [
    (minimum2[0] + maximum2[0]) / 2,
    minimum2[1],
    (minimum2[2] + maximum2[2]) / 2
  ];
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  for (const part2 of parts) {
    part2.position = part2.position.map((value, axis) => pivot[axis] + (value - pivot[axis]) * ratio);
    part2.size = part2.size.map((value) => value * ratio);
  }
};

