// src/render-common/buildings/roman-roof-tiles.ts
var ROMAN_ROOF_TILE_SCALE = 0.65;
var ROMAN_ROOF_COURSE_LENGTH_SCALE = 0.6;
var addRomanRoofTiles = ({ part: part2, parts }) => {
  const planes = parts.filter(
    (piece) => piece.surface === "roof" && piece.stage === 4 && piece.shape === "box" && piece.size[1] < 0.1
  );
  for (const plane of planes) {
    const rows = Math.ceil(
      plane.size[0] / (0.3 * ROMAN_ROOF_TILE_SCALE * ROMAN_ROOF_COURSE_LENGTH_SCALE)
    );
    const columns2 = Math.ceil(plane.size[2] / (0.22 * ROMAN_ROOF_TILE_SCALE));
    const stepX = plane.size[0] / rows;
    const stepZ = plane.size[2] / columns2;
    const rotation = plane.rotation ?? [0, 0, 0];
    const tileRotation = rotateByEuler([1, 0, 0], rotation)[1] > 0 ? [-rotation[0], rotation[1] + Math.PI, rotation[2]] : rotation;
    for (let row2 = 0; row2 < rows; row2++)
      for (let column = 0; column < columns2; column++) {
        const seed = (row2 * 17 + column * 31) % 23 / 23;
        const left = Math.max(-plane.size[2] / 2, -plane.size[2] / 2 + column * stepZ);
        const right = Math.min(plane.size[2] / 2, -plane.size[2] / 2 + (column + 1) * stepZ);
        const local = [
          -plane.size[0] / 2 + (row2 + 0.5) * stepX,
          plane.size[1] / 2 - 5e-4,
          (left + right) / 2
        ];
        const offset = rotateByEuler(local, rotation);
        part2(
          "roof",
          plane.position.map((value, axis) => value + offset[axis]),
          [
            stepX + 0.035 * ROMAN_ROOF_TILE_SCALE * ROMAN_ROOF_COURSE_LENGTH_SCALE,
            0.085 * ROMAN_ROOF_TILE_SCALE,
            right - left + 2e-3 * ROMAN_ROOF_TILE_SCALE
          ],
          4,
          "tile",
          tileRotation,
          [0.95 + seed * 0.035, 0.96 + seed * 0.03, 0.965 + seed * 0.025]
        );
      }
  }
};

