// src/render-common/buildings/roman-production-stock.ts
var addMissingRomanProductionStocks = (definition, parts, detailed) => {
  const rule2 = PRODUCTION_RULES[definition.id];
  if (!rule2 || rule2.service) return;
  const missingInputs = rule2.inputs.filter((ware) => !parts.some((part2) => part2.stock?.kind === "input" && (part2.stock.ware === ware || part2.stock.wares?.includes(ware))));
  const missingOutputs = rule2.outputs.filter((ware) => ware !== "horse" && !parts.some((part2) => part2.stock && (part2.stock.kind ?? "output") === "output" && (part2.stock.ware === ware || part2.stock.wares?.includes(ware))));
  if (!missingInputs.length && !missingOutputs.length) return;
  const bounds2 = parts.map((part2) => getRomanPartBounds(part2));
  const left = Math.min(...bounds2.map((bound) => bound.min[0])) - 0.26;
  const rear = Math.min(...bounds2.map((bound) => bound.min[2]));
  const front = Math.max(...bounds2.map((bound) => bound.max[2]));
  const categories = [
    ...missingInputs.map((ware) => ({ ware, kind: "input", aliases: void 0 })),
    ...missingOutputs.length ? [{ ware: missingOutputs[0], kind: "output", aliases: missingOutputs }] : []
  ];
  categories.forEach((category, index2) => {
    const z = rear + 0.48 + index2 * Math.max(0.5, (front - rear - 0.8) / Math.max(1, categories.length));
    const recipe = createWareRecipe(category.ware, detailed);
    const wareBounds = recipe.parts.map((part2) => getRomanPartBounds(part2));
    const bottom = Math.min(...wareBounds.map((bound) => bound.min[1]));
    const slots2 = category.kind === "output" ? 6 : 1;
    for (let slot = 0; slot < slots2; slot++) {
      const center = [
        left - (slots2 > 1 ? slot % 2 * 0.32 : 0),
        0.18 - bottom,
        z + (slots2 > 1 ? Math.floor(slot / 2) * 0.32 : 0)
      ];
      for (const piece of recipe.parts) {
        if (!detailed && category.ware === "water" && piece.shape === "cord") continue;
        parts.push({
          ...piece,
          position: piece.position.map((value, axis) => value + center[axis]),
          stock: { ware: category.ware, wares: category.aliases, kind: category.kind, slot }
        });
      }
    }
  });
};

