var addPositionedRomanWareStock = (part2, ware, slot, kind, center, detailed, yaw = 0) => {
  const recipe = createWareRecipe(ware, detailed);
  const bottom = Math.min(...recipe.parts.map((piece) => getRomanPartBounds(piece).min[1]));
  const cosine = DMath.cos(yaw), sine = DMath.sin(yaw);
  const stockPart = withBuildingStock(part2, ware, slot, kind);
  for (const piece of recipe.parts) {
    const [x, y, z] = piece.position;
    stockPart(
      piece.surface,
      [
        center[0] + x * cosine + z * sine,
        center[1] + y - bottom,
        center[2] - x * sine + z * cosine
      ],
      piece.size,
      piece.stage,
      piece.shape,
      [piece.rotation?.[0] ?? 0, (piece.rotation?.[1] ?? 0) + yaw, piece.rotation?.[2] ?? 0],
      piece.tint
    );
  }
};

