// src/render-common/buildings/roman-sawmill-timber.ts
var fitRomanSawmillTimber = (definition, recipe, detailed) => {
  if (definition.id !== 33) return;
  const timber = recipe.parts.find((part2) => !part2.stock && part2.surface === "bark" && part2.shape === "cylinder");
  if (!timber) return;
  const [x, , z] = timber.position;
  const table2 = recipe.parts.find((part2) => part2.surface === "wood" && part2.stage === 2 && Math.abs(part2.position[0] - x) < 1e-3 && Math.abs(part2.position[2] - z) < 1e-3 && Math.abs(part2.size[1] - 0.065) < 1e-3);
  if (!table2) return;
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  const canonical = createWareRecipe("logs", detailed).parts;
  const body = canonical.find((part2) => part2.surface === "bark");
  const center = [x, table2.position[1] + table2.size[1] / 2 + body.size[0] * ratio * TIMBER_LOG_LOWER_RADIUS, z];
  recipe.parts = recipe.parts.filter((part2) => !(!part2.stock && (part2.surface === "bark" || part2.surface === "endgrain") && Math.abs(part2.position[0] - x) <= timber.size[0] * 0.55 && Math.abs(part2.position[1] - timber.position[1]) <= timber.size[0] * 0.55 && Math.abs(part2.position[2] - z) <= timber.size[1] * 0.55));
  for (const part2 of canonical) recipe.parts.push({
    ...part2,
    position: part2.position.map((value, axis) => center[axis] + value * ratio),
    size: part2.size.map((value) => value * ratio)
  });
};

