var fitRomanWoodcutterTimber = (definition, recipe) => {
  if (definition.id !== WOODCUTTER_TYPE_ID) return;
  const diameter = createWareRecipe("logs", true).parts.find((part2) => part2.surface === "bark").size[0];
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  for (let slot = 0; slot < 6; slot++) {
    const parts = recipe.parts.filter((part2) => part2.stock?.ware === "logs" && part2.stock.slot === slot);
    if (!parts.length) continue;
    const bottom = Math.min(...parts.map((part2) => getRomanPartBounds(part2).min[1]));
    const target2 = diameter * ratio * (TIMBER_LOG_LOWER_RADIUS - 0.5 + Math.floor(slot / 2) * TIMBER_LOG_VERTICAL_SPAN);
    for (const part2 of parts) part2.position[1] += target2 - bottom;
  }
};

// src/render-common/buildings/sawmill-stock-recipes.ts
var withSawmillStockRecipes = (recipe) => {
  for (const part2 of recipe.parts) {
    const stock = part2.stock;
    if (!stock) continue;
    if (stock.kind === "input" && ["log", "logs"].includes(stock.ware))
      part2.stock = { ...stock, wares: SAWMILL_RECIPES.map((recipe2) => recipe2.input) };
    if (stock.kind !== "input" && ["plank", "planks"].includes(stock.ware))
      part2.stock = { ...stock, wares: SAWMILL_RECIPES.map((recipe2) => recipe2.output) };
  }
  return recipe;
};

