    back: profile.body.back,
    bit,
    clearance: profile.clearance,
    front: profile.body.front,
    ground,
    maxSlope: profile.maxSlope,
    open,
    ...labelRegions(open, terrain.width, terrain.depth),
    standRadius: profile.standRadius
